// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"altcoin":{"slug":"altcoin","cat":"basics","en":"Altcoin","contentLocale":"ja","term":"アルトコイン","aka":["アルト","Altcoin"],"short":"アルトコインとは、ビットコイン以外の暗号資産の総称で、イーサリアムやソラナのような大型銘柄から、新しく小規模な銘柄までを含みます。","body":[["「オルタナティブ（代替の）コイン」が語源で、",["ビットコイン","bitcoin"],"以外はすべてアルトコインと呼ぶのが一般的です。ただし、",["イーサリアム","ethereum"],"を別格として扱い、それ以外をアルトコインと呼ぶ人もいます。"],["アルトコインはそれぞれ目的が異なります。",["スマートコントラクト","smart-contract"],"基盤、決済、",["DeFi","defi"],"、ゲーム、",["ミームコイン","memecoin"],"など、用途も技術もさまざまです。そのため、ビットコインと同じ基準で評価するのではなく、何に使われているか、トークンの供給計画はどうか、誰が開発しているかを個別に確認する必要があります。"],["一般に、アルトコインは",["時価総額","market-capitalization"],"が小さいほど値動きが大きく、流動性も低くなりがちです。上場している取引所が限られる銘柄では、売りたいときに思った価格で売れないこともあります。"]],"example":"例えば、時価総額50億円の小型アルトコインを考えます。板が薄いため、誰かが1億円分を成行で買うと、価格が一気に20%上がることがあります。逆に同じ規模の売りが出れば、同じように大きく下がります。時価総額が数兆円規模の銘柄であれば、同じ1億円の注文で価格が動く幅はずっと小さくなります。","mistakes":["1枚の価格が安いアルトコインほど上昇余地が大きいと考えること。","板の厚さや出来高を確認せず、流動性の低い銘柄に大きな金額を入れること。","名前が有名銘柄に似ているだけの別トークンを買ってしまうこと。"],"faq":[{"q":"アルトコインとビットコインの違いは何ですか？","a":"ビットコインは最初の暗号資産で、価値の保存手段として見られることが多いのに対し、アルトコインはそれ以外の銘柄全般を指します。目的や仕組みは銘柄ごとにまったく異なります。"},{"q":"アルトシーズンとは何ですか？","a":"ビットコインよりもアルトコイン全体の値上がりが目立つ期間を指す俗語です。明確な定義はなく、いつ起こるかを事前に判断することはできません。"}],"title":"アルトコインとは？意味とビットコインとの違い","description":"アルトコインの意味、ビットコインとの違い、小型銘柄の値動きや流動性のリスクを初心者向けに解説します。","related":[["bitcoin","ビットコイン（BTC）","ビットコイン（BTC）とは、2009年に運用が始まった最初の暗号資産で、発行上限2100万枚、管理者のいないネットワークでプルーフ・オブ・ワークにより運営されています。"],["memecoin","ミームコイン","ミームコインとは、ネット上のジョークや動物、キャラクター、流行などを題材にした暗号資産で、実用性よりもコミュニティの話題性で価格が動きやすい銘柄のことです。"],["market-capitalization","時価総額（マーケットキャップ）","時価総額（マーケットキャップ）とは、暗号資産の現在価格に流通供給量を掛けた値で、その銘柄の市場規模を比べるための基本的な指標です。"],["token-listing","上場（トークン上場）","トークン上場とは、取引所が新しい暗号資産の取扱いを開始し、利用者がその取引所で入金・売買・出金できるようにすることです。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":"/coins","cta":false},"layer-2":{"slug":"layer-2","cat":"basics","en":"Layer 2 (L2)","contentLocale":"ja","term":"レイヤー2（L2）","aka":["L2","Layer 2","セカンドレイヤー"],"short":"レイヤー2（L2）とは、イーサリアムなどのレイヤー1の上で取引をまとめて処理し、その結果をL1に記録することで、手数料を下げ処理を速くする仕組みです。","body":["代表的な方式は「ロールアップ」です。L2上の多数の取引を一つにまとめ、データや証明をL1に書き込みます。不正があれば異議を申し立てられるオプティミスティック・ロールアップ（Arbitrum、Optimism、Baseなど）と、暗号学的な証明を使うZKロールアップがあります。",["ユーザーにとっての利点は手数料の安さです。L1では高くつく操作が、L2ではその何分の一、場合によっては数十分の一で済むこともあります。一方、L1とL2の間で資産を移すには",["ブリッジ","cross-chain-bridge"],"が必要で、オプティミスティック・ロールアップから公式ブリッジでL1に戻す場合は、通常約7日の待機期間があります。"],["多くの取引所は主要なL2への直接出金に対応していますが、対応ネットワークは取引所ごとに異なります。出金画面でネットワーク名を確認し、受取側の",["ウォレット","crypto-wallet"],"や取引所も同じL2に対応しているかを確かめましょう。"]],"example":["例えば、L1でのトークン交換に1回1,500円の",["ガス代","gas-fee"],"がかかり、L2では1回30円だとします。月に20回取引すると、L1では3万円、L2では600円です。1回の取引額が1万円なら、手数料の割合はL1で15%、L2で0.3%になり、少額取引ほどL2の差が大きく効いてきます。"],"mistakes":["出金先のネットワークをL1とL2で取り違え、受取側で資産が表示されなくなること。","オプティミスティック・ロールアップから公式ブリッジでL1に戻すと待機期間があることを知らずに資金を移すこと。","L2上でもガス代用のETHが必要なことを忘れること。"],"faq":[{"q":"レイヤー2は安全ですか？","a":"最終的な記録をL1に置くため安全性の一部をL1に依存しますが、運営者の権限やブリッジの設計など、L2ごとに固有のリスクがあります。"},{"q":"レイヤー2でもガス代はETHで払いますか？","a":"Arbitrum、Optimism、Baseなど多くのイーサリアムL2ではETHで支払います。ただし独自トークンで支払うL2もあるため、使う前に確認しましょう。"}],"title":"レイヤー2（L2）とは？仕組みと手数料が安い理由","description":"レイヤー2（L2）の仕組み、ロールアップの種類、手数料が安くなる理由、出金やブリッジ時の注意点を解説します。","related":[["layer-1","レイヤー1（L1）","レイヤー1（L1）とは、ビットコイン、イーサリアム、ソラナのように、独自のネットワークで取引の検証と記録を完結させる基盤となるブロックチェーンのことです。"],["gas-fee","ガス代（Gas fee）","ガス代とは、イーサリアムなどのブロックチェーンで送金やスマートコントラクトを実行するときに、ネットワークに支払う手数料のことです。"],["cross-chain-bridge","クロスチェーンブリッジ","クロスチェーンブリッジとは、異なるブロックチェーン間で暗号資産やデータを移動できるようにする仕組みで、たとえばイーサリアムのUSDCをレイヤー2に移すときに使われます。"],["ethereum","イーサリアム（ETH）","イーサリアム（ETH）とは、スマートコントラクトを実行できるブロックチェーンと、その手数料の支払いやステーキングに使われるネイティブ暗号資産ETHのことです。"],["blockchain-network","送金ネットワーク（チェーン選択）","送金ネットワークとは、暗号資産を入出金するときにどのブロックチェーン上で送るかを指定する項目で、送金側と受取側で一致させる必要があります。"]],"lesson":null,"coin":{"slug":"arbitrum","name":"Arbitrum","symbol":"ARB"},"tool":null,"cta":false},"spot-trading":{"slug":"spot-trading","cat":"trading","en":"Spot trading","contentLocale":"ja","term":"現物取引（スポット取引）","aka":["現物","スポット取引","Spot trading"],"short":"現物取引（スポット取引）とは、暗号資産をその時点の価格で実際に売買し、買った資産をそのまま受け取って保有する取引のことです。","body":[["現物取引で1 BTCを買えば、あなたの口座には実際に1 BTCが入ります。先物や",["レバレッジ取引","margin-trading"],"と違って借り入れをしていないため、価格が下がっても",["強制ロスカット","liquidation"],"されることはありません。最悪の場合でも、損失は投じた金額までです。"],["日本の取引所の現物取引には、主に「取引所（板取引）」と「",["販売所","instant-convert"],"」の2つの形式があります。板取引は利用者同士で売買し、販売所は取引所が提示する価格で売買します。販売所の価格には実質的な手数料である",["スプレッド","bid-ask-spread"],"が含まれるため、板取引よりコストが高くなりやすい点に注意が必要です。"],["注文方法は、すぐに約定する",["成行注文","market-order"],"と、価格を指定する",["指値注文","limit-order"],"が基本です。購入した資産は取引所に置いたまま保有することも、自分のウォレットに出金して管理することもできます。"]],"example":"例えば、1 ETH = 50万円のときに、現物で0.2 ETH（10万円分）を買ったとします。価格が40万円に下がれば評価額は8万円で、2万円の評価損です。それでも強制的に決済されることはなく、そのまま保有を続けられます。同じ値下がりでも、証拠金10万円・レバレッジ5倍の先物で50万円分のロングを持っていれば損失は10万円となり、証拠金がほぼ全額失われる計算です。","mistakes":["販売所と取引所（板取引）の違いを知らずに、スプレッドの大きい販売所で売買を繰り返すこと。","現物取引の画面と先物取引の画面を取り違えて注文すること。","板の薄い銘柄で大きな成行注文を出し、スリッページで不利な価格で約定すること。"],"faq":[{"q":"現物取引と先物取引の違いは何ですか？","a":"現物取引は資産そのものを売買して保有します。先物取引は将来の価格を対象にした契約を売買し、証拠金とレバレッジを使うため、強制ロスカットのリスクがあります。"},{"q":"現物取引で損失が投資額を超えることはありますか？","a":"借り入れを使わない現物取引では、損失は最大でも投じた金額までです。"}],"title":"現物取引（スポット取引）とは？仕組みと先物との違い","description":"暗号資産の現物取引（スポット取引）の仕組み、販売所と取引所の違い、先物取引との違いを具体例で解説します。","related":[["trading-pair","取引ペア（通貨ペア）","取引ペアとは、BTC/USDTやETH/JPYのように、どの資産をどの資産と交換するかを示す組み合わせのことで、取引所の売買はすべてペア単位で行われます。"],["market-order","成行注文","成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。"],["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"初めての現物取引：100から0.002 BTCへ"},"coin":null,"tool":"/compare","cta":true},"candlestick-chart":{"slug":"candlestick-chart","cat":"trading","en":"Candlestick chart","contentLocale":"ja","term":"ローソク足チャート","aka":["ローソク足","キャンドルチャート","candlestick chart"],"short":"ローソク足チャートとは、一定期間の始値・高値・安値・終値の4つの価格を、1本のローソクの形で表した価格チャートのことです。","body":[["1本のローソク足は、実体と上ヒゲ・下ヒゲでできています。実体は始値と終値の間で、終値が始値より高ければ陽線、低ければ陰線です。多くの",["暗号資産","cryptocurrency"],"取引所では陽線が緑、陰線が赤で表示されますが、設定で色を逆にできるアプリもあり、日本の証券会社のように陽線を赤や白で表すこともあります。ヒゲの先端はその期間の高値と安値です。"],"1本が表す期間は、1分足、15分足、1時間足、4時間足、日足、週足などから選べます。同じ相場でも、短い足ほど細かな値動きが見え、長い足ほど大きな流れがわかります。暗号資産は24時間取引のため、日足の区切りは取引所ごとに定められた基準時刻（多くはUTC0時）です。",["長い下ヒゲは一度売られた後に買い戻されたこと、長い上ヒゲはその逆を示します。ただし、1本の形だけで今後の値動きが決まるわけではありません。",["出来高","trading-volume"],"や上位の時間足とあわせて読むのが基本です。"]],"example":["ある日のBTC日足が、始値62,000 ",["USDT","usdt"],"、高値64,500 USDT、安値60,800 USDT、終値63,700 USDTだったとします。終値が始値より高いので陽線で、実体の長さは1,700 USDT、上ヒゲは64,500−63,700＝800 USDT、下ヒゲは62,000−60,800＝1,200 USDTです。日中に一時60,800まで下げたものの、そこから約2,900 USDT戻して引けたことが1本で読み取れます。"],"mistakes":["取引所によって日足の区切り時刻が違うことを知らず、別のアプリと比べて形が違うと混乱する。","1本の陽線や陰線だけを見て、次の値動きを決めつける。","5分足などの短い時間足のノイズに振り回され、日足や週足の流れを確認しない。"],"faq":[{"q":"ローソク足の緑と赤はどういう意味ですか？","a":"多くの暗号資産取引所では、終値が始値より高い陽線が緑、低い陰線が赤です。アプリの設定で色を入れ替えられる場合もあるので確認してください。"},{"q":"初心者はどの時間足を見ればよいですか？","a":"まず日足で大きな流れをつかみ、そのあと4時間足や1時間足で細かい動きを見るのが一般的です。短い足ほどノイズが多くなります。"}],"title":"ローソク足チャートとは？見方と読み方の基本","description":"ローソク足チャートの見方を解説。始値・高値・安値・終値の読み方、陽線と陰線、ヒゲの意味、時間足の選び方を具体例で説明します。","related":[["support-and-resistance","サポートライン・レジスタンスライン（支持線・抵抗線）","サポートライン・レジスタンスラインとは、過去に下落が止まりやすかった価格帯（支持線）と、上昇が止まりやすかった価格帯（抵抗線）をチャート上に示したものです。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"],["trading-volume","取引量（出来高）","取引量（出来高）とは、一定期間に実際に売買が成立した暗号資産の数量や金額の合計のことで、一般には24時間の値が使われます。"],["all-time-high","史上最高値（ATH）","史上最高値（ATH）とは、ある暗号資産がこれまでに記録した中で最も高い価格のことで、英語のAll-Time Highの略です。"]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"一本のローソク足：何が分かる四つの情報なのか？"},"coin":null,"tool":null,"cta":false},"last-price":{"slug":"last-price","cat":"derivatives","en":"Last traded price","contentLocale":"ja","term":"最終取引価格（直近約定価格）","aka":["最終価格","直近約定価格","ラストプライス","last price"],"short":"最終取引価格（直近約定価格）とは、その取引所の板で最後に売買が成立した価格のことで、取引画面やチャートに表示される通常の「現在値」です。","body":[["最終取引価格は、直前に約定した1件の取引の価格です。取引所ごとに板が別々なので、同じ銘柄でも取引所によって少しずつ違います。チャートの",["ローソク足","candlestick-chart"],"の終値や、アプリのトップに大きく表示される価格は、通常この最終取引価格です。"],["注意したいのは、最終取引価格は「次に自分がその価格で約定できる」ことを保証しないという点です。成行で買えば売り板の最良価格から約定し、売れば買い板の最良価格から約定します。",["スプレッド","bid-ask-spread"],"が広い銘柄や板が薄い銘柄では、最終取引価格と実際の約定価格の差が大きくなります。"],[["先物取引","futures-contract"],"では、最終取引価格のほかに",["マーク価格","mark-price"],"と",["インデックス価格","index-price"],"があります。清算の判定はマーク価格で行われることが多く、",["逆指値","stop-loss"],"の発動基準は最終取引価格とマーク価格から選べる取引所もあります。どの価格を基準にしているかを確認してから注文してください。"]],"example":"あるトークンの最終取引価格が0.500 USDTと表示されていますが、板を見ると最良の売り気配が0.508 USDT、最良の買い気配が0.492 USDTだとします。この状態で成行で2,000枚買うと、少なくとも0.508 USDTで約定するため、支払いは1,016 USDT以上になります。表示価格で計算した1,000 USDTより1.6%以上高く、直後に成行で売れば0.492 USDT以下での約定となります。","mistakes":["表示されている最終取引価格で必ず約定できると思い、成行注文を出す。","逆指値の発動基準が最終取引価格なのかマーク価格なのかを確認しない。","取引所ごとに最終取引価格が違うのを、どちらかの表示の誤りだと考える。"],"faq":[{"q":"最終取引価格とマーク価格はどちらが正しいですか？","a":"どちらも正しく、用途が違います。最終取引価格は実際に約定した価格、マーク価格は清算や含み損益の判定に使う公正価格です。"},{"q":"なぜ取引所によって価格が違うのですか？","a":"取引所ごとに別々の板で売買が行われているからです。通常は裁定取引によって差は小さく保たれます。"}],"title":"最終取引価格とは？マーク価格や約定価格との違い","description":"最終取引価格（直近約定価格）の意味、実際の約定価格やマーク価格との違い、スプレッドが広い銘柄での注意点を具体例で解説します。","related":[["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。"],["index-price","インデックス価格","インデックス価格とは、複数の主要な現物取引所の価格を加重平均して算出した、その暗号資産の現物の基準価格のことで、マーク価格や資金調達率の計算に使われます。"],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"画面に表示された価格が、なぜ約定価格と違うのか？"},"coin":null,"tool":null,"cta":false},"funding-rate-arbitrage":{"slug":"funding-rate-arbitrage","cat":"derivatives","en":"Funding rate arbitrage","contentLocale":"ja","term":"資金調達率アービトラージ（FRアービトラージ）","aka":["FRアービトラージ","ファンディングレートアービトラージ","FR裁定","キャッシュ・アンド・キャリー"],"short":"資金調達率アービトラージとは、現物を買うと同時に同じ数量の無期限先物をショートし、価格変動の影響を打ち消しながら資金調達率の受け取りを狙う取引です。","body":[[["資金調達率","funding-rate"],"がプラスのとき、",["無期限先物","perpetual-futures"],"のショートは",["ロング","long-and-short"],"から定期的に支払いを受け取ります。ただしショートだけを持つと価格上昇で損をするため、同じ数量の現物を買っておきます。こうすると価格が上下しても現物と先物の損益がほぼ相殺され、手元には資金調達率の受け取りが残ります。これをデルタニュートラルと呼びます。"],["収益は資金調達率次第で、相場の状況によって大きく変わり、マイナスに転じればショート側が支払う側になります。売買手数料、現物と先物の価格差の変動、先物口座の証拠金不足による清算などのリスクもあります。急騰時にショートの証拠金が足りなくなると、現物が無事でもショートだけ清算され、",["ヘッジ","hedging"],"が崩れます。"],"取引所によっては、この取引を自動で行う商品を提供しています。資金調達率の精算間隔は取引所や銘柄で8時間、4時間、1時間などと異なるため、比較するときは年率や1日あたりに換算してください。"],"example":["BTCが60,000 USDTのとき、現物を1 BTC買い、無期限先物で1 BTCをショートしたとします。資金調達率が+0.01%で8時間ごとの精算なら、1回の受け取りは60,000×0.0001＝6 ",["USDT","usdt"],"、1日18 USDT、30日で540 USDTです。現物と先物の往復手数料が合計約120 USDTかかれば、残りは約420 USDT、元本に対して約0.7%です。途中で資金調達率がマイナスになれば、受け取りは支払いに変わります。"],"mistakes":["資金調達率が今後も同じ水準で続くと考えて、利回りを年率換算で過大に見積もる。","先物のショートに高いレバレッジをかけ、急騰時にショートだけが清算されてヘッジが崩れる。","往復の手数料やスリッページを計算に入れず、短期間で出入りして利益が残らない。"],"faq":[{"q":"資金調達率アービトラージはリスクがないのですか？","a":"価格変動の影響は小さくなりますが、資金調達率のマイナス転換、先物の清算、取引所のリスク、手数料などのリスクがあります。"},{"q":"どれくらいの資金が必要ですか？","a":"現物の購入資金に加えて、先物のショートの証拠金も必要です。清算を防ぐため、先物口座には余裕を持った証拠金を入れておくのが一般的です。"}],"title":"資金調達率アービトラージとは？仕組みとリスク","description":"資金調達率（ファンディングレート）アービトラージの仕組み、現物買いと先物ショートで収益を得る計算例、主なリスクを解説します。","related":[["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["arbitrage","アービトラージ（裁定取引）","アービトラージ（裁定取引）とは、同じ資産の価格差が取引所間や市場間で生じたときに、安い方で買って高い方で売り、その差を利益にする取引です。"],["hedging","ヘッジ（リスクヘッジ）","ヘッジとは、保有している資産の値下がりなどのリスクを抑えるために、反対方向に動くポジションを持って損失を相殺する取引のことです。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"価格は横ばい、残高は減少？コストを意識して最終関門をクリアせよ"},"coin":null,"tool":"/funding-rates","cta":false},"hardware-wallet":{"slug":"hardware-wallet","cat":"wallets-security","en":"Hardware wallet","contentLocale":"ja","term":"ハードウェアウォレット","aka":["hardware wallet","ハードウォレット","HW"],"short":"ハードウェアウォレットとは、秘密鍵を専用の小型デバイス内に保管し、送金の署名を端末の中だけで行う物理的な暗号資産ウォレットです。","body":[["LedgerやTrezorなどが代表的な製品です。パソコンやスマホにつないでも",["秘密鍵","private-key"],"は外に出ず、取引内容をデバイスの画面で確認して物理ボタンで承認する仕組みになっています。"],"パソコンがマルウェアに感染していても、デバイス上で承認しない限り送金されない点が大きな強みです。ただし、画面の送金先や承認内容をよく読まずにボタンを押せば、詐欺の取引にも署名できてしまいます。",["購入は公式サイトか正規販売店に限りましょう。初期設定時にデバイス自身が",["シードフレーズ","seed-phrase"],"を生成するのが正常で、最初からシードフレーズが書かれたカードが同梱されていたら不正品を疑うべきです。"]],"example":["あなたが3 ETHを友人に送るとします。パソコンの",["ウォレット","crypto-wallet"],"画面で送金を作成すると、ハードウェアウォレットの画面に送金先",["アドレス","wallet-address"],"と3 ETHという金額が表示されます。アドレスの先頭6文字と末尾6文字が友人から受け取ったものと一致するかを確認し、合っていればボタンで承認します。もしマルウェアがアドレスを書き換えていれば、ここで不一致に気付けます。"],"mistakes":["フリマアプリなどで中古や開封済みの製品を購入すること。","デバイスの画面を確認せず、パソコン側の表示だけを信じて承認すること。","シードフレーズを入力するよう求める偽の「ファームウェア更新」サイトに従うこと。"],"faq":[{"q":"ハードウェアウォレットが壊れたら資産は失われますか？","a":"シードフレーズがあれば、新しいデバイスや対応ウォレットで復元できます。資産はブロックチェーン上にあり、デバイスは鍵を守る道具にすぎません。"},{"q":"ハードウェアウォレットのメーカーが倒産したらどうなりますか？","a":"多くの製品は業界標準のシードフレーズ方式を採用しているため、他の対応ウォレットで復元できるのが一般的です。購入前に対応規格を確認しておくと安心です。"}],"title":"ハードウェアウォレットとは？仕組みと選び方","description":"ハードウェアウォレットの仕組み、ハッキングに強い理由、購入時や送金承認時に注意すべきポイントを初心者向けに解説します。","related":[["cold-wallet","コールドウォレット（コールドストレージ）","コールドウォレットとは、秘密鍵をインターネットから切り離した環境で保管する暗号資産の保管方法で、遠隔からのハッキングを受けにくいのが特徴です。"],["seed-phrase","シードフレーズ（リカバリーフレーズ）","シードフレーズとは、ウォレットの秘密鍵をすべて復元できる12語または24語の英単語の並びで、ウォレットのマスターキーにあたるものです。"],["private-key","秘密鍵（プライベートキー）","秘密鍵とは、暗号資産のアドレスから送金するための電子署名を作る秘密の数値で、これを持つ人がそのアドレスの資産を自由に動かせます。"],["address-poisoning","アドレスポイズニング","アドレスポイズニングとは、本物の送金先とよく似たアドレスから少額や0円の取引を送りつけ、取引履歴から偽アドレスをコピーさせて誤送金を誘う詐欺です。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"私のコインはどこ？取引所とウォレットの違い"},"coin":null,"tool":null,"cta":false},"governance-token":{"slug":"governance-token","cat":"defi","en":"Governance token","contentLocale":"ja","term":"ガバナンストークン","aka":["governance token","ガバナンス・トークン","投票トークン"],"short":"ガバナンストークンとは、DeFiやDAOなどのプロジェクトで、運営方針や仕様変更に関する投票に参加する権利を表すトークンです。","body":["UniswapのUNIやAaveのAAVEが代表例です。保有量に応じて投票権が与えられ、手数料の配分、新機能の追加、トレジャリー（共有資金）の使い道などを決める提案に投票できます。",["ガバナンストークンは、",["エアドロップ","airdrop"],"や",["流動性","liquidity"],"提供の報酬として配られることが多く、取引所で売買もされています。価格はプロジェクトへの期待や市場全体の動きで変わります。"],["注意したいのは、ガバナンストークンは株式とは違い、配当や利益分配の権利が必ずあるわけではないことです。価値の根拠を投票権以外に持たないトークンもあります。",["トークノミクス","tokenomics"],"（発行量、配分、",["ロック解除","token-unlock"],"のスケジュール）を確認することが大切です。"]],"example":["あるプロジェクトのガバナンストークンが総発行量10億枚で、そのうち現在流通しているのは2億枚だとします。今後3年で残りの8億枚のうち4億枚がチームや投資家に段階的に解除される予定なら、",["流通量","circulating-supply"],"は3年で3倍の6億枚になります。需要が変わらなければ、売り圧力が増えやすい構造です。投票権の有無だけでなく、供給の増え方も価値に影響します。"],"mistakes":["ガバナンストークンを持てば、株式のように配当がもらえると思い込むこと。","ロック解除のスケジュールを確認せず、大量解除の直前に購入すること。","投票権があるのに、少額だから意味がないと考えて仕組みを理解しないまま保有すること。"],"faq":[{"q":"ガバナンストークンを持つと何ができますか？","a":"プロジェクトの提案への投票や、一定量以上の保有で提案そのものを出すことができます。ステーキングや手数料分配の仕組みを持つトークンもありますが、プロジェクトごとに異なります。"},{"q":"ガバナンストークンと普通のトークンの違いは何ですか？","a":"主な違いは、運営の意思決定に参加する投票権が付いていることです。決済や手数料支払い用のトークンとは役割が異なりますが、1つのトークンが複数の役割を持つこともあります。"}],"title":"ガバナンストークンとは？投票権と価値の見方","description":"ガバナンストークンの意味、DAOでの投票の仕組み、配当との違い、流通量やロック解除スケジュールの確認ポイントを解説します。","related":[["dao","DAO（分散型自律組織）","DAO（分散型自律組織）とは、特定の経営者ではなく、トークン保有者などの参加者がブロックチェーン上の投票で意思決定を行う組織の形態です。"],["tokenomics","トークノミクス","トークノミクスとは、暗号資産トークンの供給量、配分、発行スケジュール、用途、焼却などをまとめた経済設計の全体像のことです。"],["airdrop","エアドロップ","エアドロップとは、プロジェクトが特定の条件を満たしたウォレットやユーザーに、トークンを無料で配布することです。"],["coin-vs-token","コインとトークンの違い","コインとトークンの違いとは、コインは独自のブロックチェーンのネイティブ資産であり、トークンは既存のブロックチェーン上でスマートコントラクトにより発行される資産だという区別です。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"usdt":{"slug":"usdt","cat":"stablecoins","en":"USDT (Tether)","contentLocale":"ja","term":"USDT（テザー）","aka":["テザー","Tether","USDT","USDテザー"],"short":"USDT（テザー）とは、Tether社が発行する米ドル連動型のステーブルコインで、暗号資産取引の基軸通貨として最も広く使われているもののひとつです。","body":["USDTは、発行体が保有する現金や米国短期国債などの準備資産を裏付けに、1 USDTが約1ドルになるよう設計されています。Tether社は準備資産の内訳を定期的に公表しています。",[["イーサリアム","ethereum"],"（ERC20）、トロン（TRC20）、ソラナ、TONなど多くの",["ブロックチェーン","blockchain"],"で発行されています。取引所間で送金するときは、送金側と受取側で同じネットワークを選ぶ必要があります。ネットワークごとに手数料や着金時間が異なります。"],["注意点として、USDTは米ドルそのものではなく、発行体への信頼に依存しています。また発行体は、不正利用が疑われる",["アドレス","wallet-address"],"のUSDTを凍結できます。各国の規制で扱いが異なり、EUではMiCAの要件との関係で取り扱いを制限した取引所もあります。"]],"example":"あなたが取引所AからBへ2,000 USDTを送るとします。Aの出金画面で、仮にERC20の手数料が5 USDT、TRC20が1 USDT、ソラナが1 USDTだったとします。Bの入金画面がTRC20とソラナに対応しているなら、どちらかを選んで1,999 USDTを受け取れます。ERC20に対応していないBに、ERC20で送れば反映されない恐れがあるため、手数料より先にネットワークの一致を確認します。","mistakes":["USDTを銀行預金と同じように、元本が保証された米ドルだと考えること。","送金時にネットワークを確認せず、受取側が対応していないチェーンで送ること。","P2P取引で、相手の入金確認前にUSDTをリリースしてしまうこと。"],"faq":[{"q":"USDTとUSDCの違いは何ですか？","a":"どちらも米ドル連動のステーブルコインですが、発行体が異なります。USDTはTether社、USDCはCircle社が発行し、準備資産の開示方法や各国の規制への対応状況も異なります。"},{"q":"日本の取引所でUSDTは買えますか？","a":"日本では、ステーブルコインは資金決済法上の電子決済手段として扱われ、取り扱うには登録が必要です。国内での取り扱い状況は変わる可能性があるため、利用する業者の最新の案内を確認しましょう。"}],"title":"USDT（テザー）とは？仕組みと送金時の注意点","description":"USDT（テザー）の意味、米ドル連動の仕組み、ERC20・TRC20などネットワークの違い、送金や保有時に知っておくべき注意点を解説します。","related":[["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["usdc","USDC（USDコイン）","USDCとは、米国のCircle社が発行する米ドル連動型のステーブルコインで、現金と米国短期国債などを裏付けに1 USDCが約1ドルになるよう設計されています。"],["blockchain-network","送金ネットワーク（チェーン選択）","送金ネットワークとは、暗号資産を入出金するときにどのブロックチェーン上で送るかを指定する項目で、送金側と受取側で一致させる必要があります。"],["depeg","デペッグ（Depeg）","デペッグとは、1ドルなど特定の価値に連動するよう設計されたステーブルコインやトークンの価格が、その目標値から大きく離れてしまう状態のことです。"],["p2p-trading","P2P取引（個人間取引）","P2P取引とは、取引所が仲介役となり、利用者同士が銀行振込などの法定通貨とUSDTなどの暗号資産を直接交換する取引方法です。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDTは米ドルですか？なぜ暗号資産を買う時によく見かけるの？"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"synthetic-dollar":{"slug":"synthetic-dollar","cat":"stablecoins","en":"Synthetic dollar (delta-neutral stablecoin)","contentLocale":"ja","term":"合成ドル（デルタニュートラル型ステーブルコイン）","aka":["シンセティックドル","デルタニュートラル型ステーブルコイン","synthetic dollar"],"short":"合成ドルとは、暗号資産の現物保有と無期限先物のショートを組み合わせて価格変動を相殺し、ドルに近い価値を保つよう設計されたトークンのことです。代表例はEthenaのUSDeです。","body":[["たとえばETHを現物で持ちながら、同じ量のETHを",["無期限先物（パーペチュアル）","perpetual-futures"],"でショートすると、ETHが上がっても下がっても損益がほぼ打ち消し合います。この状態を「デルタニュートラル」と呼び、ポジション全体の価値をドル建てで安定させます。"],["収益の源泉は、ショート側が受け取る",["資金調達率（ファンディングレート）","funding-rate"],"と、担保に使う",["ステーキング","staking"],"資産の報酬です。",["強気相場","bull-market"],"で資金調達率がプラスのときは利回りが高くなりやすい一方、資金調達率がマイナスになるとショート側が支払う立場になり、利回りが下がったり準備金が減ったりします。"],["銀行預金で裏付けられた",["ステーブルコイン","stablecoin"],"とは仕組みが根本的に違い、取引所の破綻リスク、資金調達率の長期的なマイナス、担保資産の",["デペッグ","depeg"],"といった独自のリスクがあります。発行体が公開する準備金や保険基金の情報を確認することが大切です。"]],"example":"ETHが2,000ドルのとき、あるプロトコルが10 ETH（20,000ドル分）を現物で保有し、同時に10 ETHをショートしたとします。ETHが1,800ドルに下がると現物は2,000ドルの含み損、ショートは2,000ドルの含み益で、合計は約20,000ドルのまま保たれます。このショートに8時間ごとに0.01%の資金調達率が支払われるとすると、1日3回で0.03%、20,000ドルに対して1日約6ドルの収益になります。逆に資金調達率が−0.01%になれば、同じ額を支払う側に回ります。","mistakes":["合成ドルを銀行預金で裏付けられたUSDCなどと同じものだと考えてしまう。","表示されている利回りが固定だと思い込み、資金調達率がマイナスになると下がることを見落とす。","ヘッジに使われている取引所のカウンターパーティリスクを考慮しない。"],"faq":[{"q":"USDeは安全ですか？","a":"価格変動はヘッジされていますが、資金調達率のマイナス、取引所の破綻、担保資産の問題といった独自のリスクがあります。法定通貨担保型とは別物として、仕組みとリスクを理解したうえで扱う必要があります。"},{"q":"合成ドルの利回りはどこから来ますか？","a":"主に無期限先物のショートで受け取る資金調達率と、担保に使うステーキング資産の報酬です。そのため市場環境によって利回りは大きく変わります。"}],"title":"合成ドルとは？デルタニュートラル型ステーブルコイン","description":"合成ドル（デルタニュートラル型ステーブルコイン）の仕組み、資金調達率から利回りが生まれる理由、USDeを例にしたリスクを解説します。","related":[["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["hedging","ヘッジ（リスクヘッジ）","ヘッジとは、保有している資産の値下がりなどのリスクを抑えるために、反対方向に動くポジションを持って損失を相殺する取引のことです。"],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["depeg","デペッグ（Depeg）","デペッグとは、1ドルなど特定の価値に連動するよう設計されたステーブルコインやトークンの価格が、その目標値から大きく離れてしまう状態のことです。"]],"lesson":null,"coin":{"slug":"ethena-usde","name":"Ethena USDe","symbol":"USDE"},"tool":"/funding-rates","cta":false}});
